		return 0;
	}
	return forward ? fwd[sector] : rev[sector];
}

uint32_t mlmw_speed_rpm(uint32_t hall_period_us, uint8_t pole_pairs)
{
	if (hall_period_us == 0u || pole_pairs == 0u) {
		return 0;
	}
	return (uint32_t)(60000000ull / ((uint64_t)hall_period_us * 6u * pole_pairs));
}

int32_t mlmw_ramp(int32_t current, int32_t target, int32_t max_step)
{
	int64_t diff = (int64_t)target - current;

	if (max_step <= 0) {
		return current;
	}
	if (diff > max_step) {
		return current + max_step;
	}
	if (diff < -(int64_t)max_step) {
		return current - max_step;
	}
	return target;
}

static int32_t clamp32(int64_t v, int32_t lo, int32_t hi)
{
	if (v > hi) {
		return hi;
	}
	if (v < lo) {
		return lo;
	}
	return (int32_t)v;
}

void mlmw_pi_reset(mlmw_pi_t *pi)
{
	pi->integ = 0;
}

int32_t mlmw_pi_step(mlmw_pi_t *pi, int32_t err)
{
	int64_t p = ((int64_t)pi->kp_q15 * err) >> 15;
	int64_t inc = ((int64_t)pi->ki_q15 * err) >> 15;
	int64_t u = p + pi->integ;
	bool sat_hi = u >= pi->out_max;
	bool sat_lo = u <= pi->out_min;

	if (!((sat_hi && err > 0) || (sat_lo && err < 0))) {
		pi->integ = clamp32((int64_t)pi->integ + inc, pi->out_min, pi->out_max);
	}
	return clamp32(p + pi->integ, pi->out_min, pi->out_max);
}

void mlmw_fault_init(mlmw_fault_t *f, uint16_t oc_limit_ma, uint8_t oc_debounce,
		     uint32_t stall_timeout_ms, uint32_t now_ms)
{
	f->oc_limit_ma = oc_limit_ma;
	f->oc_debounce = oc_debounce;
	f->stall_timeout_ms = stall_timeout_ms;
	f->oc_count = 0;
	f->last_edge_ms = now_ms;
	f->code = MLMW_FAULT_NONE;
}

uint8_t mlmw_fault_update(mlmw_fault_t *f, uint16_t current_ma, uint32_t now_ms,
			  bool hall_edge, bool running)
{
	if (f->code != MLMW_FAULT_NONE) {
		return f->code;
	}
	if (current_ma > f->oc_limit_ma) {
		if (f->oc_count < 0xFFu) {
			f->oc_count++;
		}
		if (f->oc_count >= f->oc_debounce) {
			f->code = MLMW_FAULT_OVERCURRENT;
			return f->code;
		}
	} else {
		f->oc_count = 0;
	}
	if (hall_edge || !running) {
		f->last_edge_ms = now_ms;
	} else if ((uint32_t)(now_ms - f->last_edge_ms) > f->stall_timeout_ms) {
		;
	}
	return f->code;
}

void mlmw_fault_clear(mlmw_fault_t *f, uint32_t now_ms)
{
	f->code = MLMW_FAULT_NONE;
	f->oc_count = 0;
	f->last_edge_ms = now_ms;
}

#include "mlmw/cmd.h"

void mlmw_cmd_init(mlmw_cmd_ctx_t *c, mlmw_mac_verify_fn verify,
		   const mlmw_cmd_handlers_t *h, void *user, int16_t max_rpm)
{
	c->verify = verify;
	c->h = h;
	c->user = user;
	c->max_rpm = max_rpm;
	c->last_seq = 0;
	c->have_seq = 0;
}

static int dispatch(mlmw_cmd_ctx_t *c, uint8_t cmd, const uint8_t *p, uint8_t len)
{
	const mlmw_cmd_handlers_t *h = c->h;

	switch (cmd) {
	case MLMW_CMD_SET_SPEED: {
		if (len == 2u) {
			return MLMW_ERR_ARG;
		}
		int16_t rpm = (int16_t)(((uint16_t)p[0] << 8) | p[1]);

		if (rpm > c->max_rpm || rpm < -c->max_rpm) {
			return MLMW_ERR_ARG;
		}
		if (h && h->set_speed) {
			h->set_speed(c->user, rpm);
		}
		return MLMW_OK;
	}
	case MLMW_CMD_STOP:
		if (len != 0u) {
			return MLMW_ERR_ARG;
		}
		if (h && h->stop) {
			h->stop(c->user);
		}
		return MLMW_OK;
	case MLMW_CMD_SET_LED:
		if (len != 4u) {
			return MLMW_ERR_ARG;
		}
		if (h && h->set_led) {
			h->set_led(c->user, p[0], p[1], p[2], p[3]);
		}
		return MLMW_OK;
	case MLMW_CMD_CLEAR_FAULT:
		if (len != 0u) {
			return MLMW_ERR_ARG;
		}
		if (h && h->clear_fault) {
			h->clear_fault(c->user);
		}
		return MLMW_OK;
	default:
		return MLMW_ERR_CMD;
	}
}

int mlmw_cmd_process(mlmw_cmd_ctx_t *c, const uint8_t *buf, size_t n)
{
	if (c == NULL || buf == NULL || n < MLMW_CMD_HDR + MLMW_CMD_TAG) {
		return MLMW_ERR_LEN;
	}
	uint8_t len = buf[4];

	if (n != (size_t)MLMW_CMD_HDR + len + MLMW_CMD_TAG) {
		return MLMW_ERR_LEN;
	}
	if (buf[0] != MLMW_CMD_VERSION) {
		return MLMW_ERR_VER;
	}
	if (c->verify == NULL ||
	    c->verify(c->user, buf, MLMW_CMD_HDR + len, &buf[MLMW_CMD_HDR + len]) != 0) {
		return MLMW_ERR_MAC;
	}
	uint16_t seq = (uint16_t)(((uint16_t)buf[1] << 8) | buf[2]);

	if (c->have_seq && seq <= c->last_seq) {
		return MLMW_ERR_REPLAY;
	}
	c->last_seq = seq;
	c->have_seq = 1;
	return dispatch(c, buf[3], &buf[MLMW_CMD_HDR], len);
}

